package orchestrator

import (
	"testing"
	"time"
)

// ep is a test-episode builder: packable by default, never packaged, no
// cooldown — the common case each table case then overrides.
func ep(id string) Episode {
	return Episode{ItemID: id, Packable: true}
}

// serial is a test-serial builder: streams enabled, canonical episode order.
func serial(lib int64, episodes ...Episode) Serial {
	return Serial{LibraryID: lib, StreamsEnabled: true, Episodes: episodes}
}

var (
	// testNow is the frontier's evaluation clock; coolPast is a deadline in
	// the past (cooldown elapsed — eligible), coolFuture one still running.
	testNow    = time.Date(2026, 10, 9, 12, 0, 0, 0, time.UTC)
	coolPast   = testNow.Add(-time.Hour)
	coolFuture = testNow.Add(time.Hour)
)

// TestFrontier is the acceptance test for spec "Watch-driven packaging
// frontier" (all three scenarios) plus the cooldown/packaged/eligibility
// negatives. Each case feeds Frontier one serial-shaped snapshot and asserts
// the exact job set (item ids in order).
func TestFrontier(t *testing.T) {
	cases := []struct {
		name    string
		in      FrontierIn
		wantIDs []string // empty asserts NO jobs
	}{
		// Scenario 1: watching episode K fronts exactly K+1.
		{
			name: "watched_episode_fronts_next_only",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"), ep("e3"))},
				Watched: map[string]bool{"e2": true},
				Now:     testNow,
			},
			wantIDs: []string{"e3"},
		},
		{
			name: "last_watched_wins_over_gap",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"), ep("e3"), ep("e4"))},
				Watched: map[string]bool{"e1": true, "e3": true},
				Now:     testNow,
			},
			wantIDs: []string{"e4"},
		},
		{
			name: "fully_watched_serial_fronts_nothing",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), ep("e2"))},
				Watched: map[string]bool{"e1": true, "e2": true},
				Now:     testNow,
			},
		},

		// Scenario 2a: fresh serial fronts its eager pilot E1.
		{
			name: "fresh_serial_fronts_pilot",
			in: FrontierIn{
				Serials: []Serial{serial(2, ep("p1"), ep("p2"))},
				Watched: map[string]bool{},
				Now:     testNow,
			},
			wantIDs: []string{"p1"},
		},
		// Scenario 2b: movies wait for play — they are absent from the input
		// by construction, so even watched movie ids never mint a job.
		{
			name:    "watched_movies_alone_front_nothing",
			in:      FrontierIn{Serials: nil, Watched: map[string]bool{"movie-a": true, "movie-b": true}, Now: testNow},
			wantIDs: nil,
		},

		// Scenario 3: the streams-disabled library gate skips the serial.
		{
			name: "streams_disabled_library_skipped",
			in: FrontierIn{
				Serials: []Serial{{LibraryID: 3, StreamsEnabled: false, Episodes: []Episode{ep("d1"), ep("d2")}}},
				Watched: map[string]bool{"d1": true},
				Now:     testNow,
			},
		},

		// Eligibility negatives on the candidate.
		{
			name: "already_packaged_candidate_not_reenqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, Packaged: true})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "candidate_inside_failure_cooldown_not_reenqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, CoolUntil: coolFuture})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "candidate_cooldown_elapsed_is_enqueued",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: true, CoolUntil: coolPast})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
			wantIDs: []string{"e2"},
		},
		{
			name: "unpackable_classification_candidate_skipped",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("e1"), Episode{ItemID: "e2", Packable: false})},
				Watched: map[string]bool{"e1": true},
				Now:     testNow,
			},
		},
		{
			name: "empty_serial_fronts_nothing",
			in: FrontierIn{
				Serials: []Serial{serial(1)},
				Watched: map[string]bool{},
				Now:     testNow,
			},
		},
		{
			name: "two_serials_front_independently",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("a1"), ep("a2")),
					serial(1, ep("b1"), ep("b2")),
				},
				Watched: map[string]bool{"a2": true, "b1": true},
				Now:     testNow,
			},
			wantIDs: []string{"b2"},
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			got, _, _ := Frontier(tc.in)
			ids := make([]string, len(got))
			for i, j := range got {
				ids[i] = j.ItemID
			}
			if len(ids) != len(tc.wantIDs) {
				t.Fatalf("Frontier() job ids = %v, want %v", ids, tc.wantIDs)
			}
			for i := range ids {
				if ids[i] != tc.wantIDs[i] {
					t.Fatalf("Frontier() job ids = %v, want %v", ids, tc.wantIDs)
				}
			}
		})
	}
}

// TestFrontierJobShape pins the attribution fields (library + reason) that
// the operator log and the enqueue site consume.
func TestFrontierJobShape(t *testing.T) {
	in := FrontierIn{
		Serials: []Serial{serial(7, ep("w1"), ep("w2"))},
		Watched: map[string]bool{"w1": true},
		Now:     testNow,
	}
	got, _, _ := Frontier(in)
	if len(got) != 1 {
		t.Fatalf("Frontier() = %d jobs, want 1", len(got))
	}
	if got[0].LibraryID != 7 || got[0].Reason != reasonNext {
		t.Fatalf("Frontier() job = %+v, want library 7 reason %q", got[0], reasonNext)
	}

	pilot, _, _ := Frontier(FrontierIn{Serials: in.Serials, Watched: map[string]bool{}, Now: testNow})
	if len(pilot) != 1 || pilot[0].ItemID != "w1" || pilot[0].Reason != reasonPilot {
		t.Fatalf("Frontier() pilot = %+v, want w1/%q", pilot, reasonPilot)
	}
}

// TestFrontierWorkingSet pins the churn-break contract: the working set is
// the frontier POSITION of every gated, not-fully-watched serial — pinned
// whether or not a job was emitted. A packaged or cooling position emits no
// job today but is exactly what the frontier repacks after any eviction;
// pinning only job-emitting ticks empties the set the moment fresh builds
// exist (postmortem 2026-10-31, F3).
func TestFrontierWorkingSet(t *testing.T) {
	in := FrontierIn{
		Serials: []Serial{
			// job-eligible position; packaged position (no job, still fronted);
			serial(1, ep("a1"), Episode{ItemID: "a2", Packable: true, Packaged: true}, ep("a3")),
			// cooling position (no job, still fronted)
			serial(2, ep("b1"), Episode{ItemID: "b2", Packable: true, CoolUntil: coolFuture}),
			// streams-disabled gate: nothing fronts
			{LibraryID: 3, StreamsEnabled: false, Episodes: []Episode{ep("c1"), ep("c2")}},
			// fully watched: nothing is past the frontier
			serial(4, ep("d1"), ep("d2")),
		},
		Watched: map[string]bool{"a1": true, "b1": true, "d1": true, "d2": true},
		Now:     testNow,
	}
	jobs, pinned, _ := Frontier(in)
	if len(jobs) != 0 {
		t.Fatalf("Frontier() jobs = %v, want none (positions packaged/cooling/gated)", jobs)
	}
	want := map[string]bool{"a2": true, "b2": true}
	if len(pinned) != len(want) {
		t.Fatalf("Frontier() working set = %v, want %v", pinned, want)
	}
	for id := range want {
		if !pinned[id] {
			t.Fatalf("Frontier() working set missing %q (got %v)", id, pinned)
		}
	}

	// The eligible-only snapshot still fronts AND jobs its positions.
	clear := FrontierIn{
		Serials: []Serial{serial(1, ep("a1"), ep("a2"), ep("a3"))},
		Watched: map[string]bool{"a1": true},
		Now:     testNow,
	}
	clearJobs, clearPinned, _ := Frontier(clear)
	if len(clearJobs) != 1 || clearJobs[0].ItemID != "a2" {
		t.Fatalf("Frontier() jobs = %v, want [a2]", clearJobs)
	}
	if !clearPinned["a2"] {
		t.Fatalf("Frontier() working set = %v, want a2 (jobs ⊆ working set)", clearPinned)
	}
}

// TestOnPlay is the pack-on-play acceptance table (movies pack on play,
// never pre-warmed): the same eligibility rule the sweep enforces, applied
// at the play that asks for it.
func TestOnPlay(t *testing.T) {
	cases := []struct {
		name string
		e    Episode
		want bool
	}{
		{"packable_unpackaged_no_cooldown_enqueues", ep("m1"), true},
		{"already_packaged_no_enqueue", Episode{ItemID: "m1", Packable: true, Packaged: true}, false},
		{"inside_cooldown_no_enqueue", Episode{ItemID: "m1", Packable: true, CoolUntil: coolFuture}, false},
		{"elapsed_cooldown_enqueues", Episode{ItemID: "m1", Packable: true, CoolUntil: coolPast}, true},
		{"unpackable_classification_no_enqueue", Episode{ItemID: "m1", Packable: false}, false},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			if got := OnPlay(tc.e, testNow); got != tc.want {
				t.Fatalf("OnPlay(%+v) = %v, want %v", tc.e, got, tc.want)
			}
		})
	}
}

// TestRepacks is the integrity sweep's acceptance test for the pure repack
// judge (D4's policy half; probe e3a94ff9390eec25): exactly the unhealthy
// items come back as repack jobs, healthy items never job, and empty input
// yields an empty — never nil — slice.
func TestRepacks(t *testing.T) {
	t.Run("broken_items_repack_healthy_never", func(t *testing.T) {
		got := Repacks([]IntegrityItem{
			{ItemID: "it_ok", Healthy: true},
			{ItemID: "it_bad", Healthy: false},
			{ItemID: "it_fine", Healthy: true},
			{ItemID: "it_worse", Healthy: false},
		})
		if len(got) != 2 {
			t.Fatalf("Repacks() = %+v, want exactly the 2 unhealthy jobs", got)
		}
		for i, want := range []string{"it_bad", "it_worse"} {
			if got[i].ItemID != want {
				t.Fatalf("job %d item = %q, want %q (input order, unhealthy only)", i, got[i].ItemID, want)
			}
			if got[i].Reason != "repack" {
				t.Fatalf("job %d reason = %q, want %q", i, got[i].Reason, "repack")
			}
		}
	})

	t.Run("healthy_items_never_job", func(t *testing.T) {
		if got := Repacks([]IntegrityItem{{ItemID: "it_ok", Healthy: true}}); len(got) != 0 {
			t.Fatalf("Repacks(all healthy) = %+v, want no jobs", got)
		}
	})

	t.Run("empty_input_empty_non_nil_slice", func(t *testing.T) {
		got := Repacks(nil)
		if got == nil {
			t.Fatal("Repacks(nil) = nil, want an empty non-nil slice (the sweep iterates it)")
		}
		if len(got) != 0 {
			t.Fatalf("Repacks(nil) = %+v, want empty", got)
		}
	})
}

// TestFrontierBoundedPinSet pins the bounded working set (D1): the pinned
// prefix walks serials most recently watched first, a stampless serial
// sorts oldest, and a position that would overflow PinCapBytes ends the
// walk — later (even cheaper) positions stay unpinned. The pinned set's
// accumulated bytes never exceed the cap, jobs emit only from pinned
// positions, and a non-positive cap is unbounded (the zero value's
// behavior).
func TestFrontierBoundedPinSet(t *testing.T) {
	cases := []struct {
		name       string
		in         FrontierIn
		wantPinned []string // exact pinned item set
		wantJobs   []string // exact job ids in emission order
	}{
		{
			name: "recency_orders_the_walk_most_recent_first",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("old1"), ep("old2")), // stamped two hours ago
					serial(1, ep("new1"), ep("new2")), // stamped one minute ago
					serial(1, ep("mid1"), ep("mid2")), // stamped an hour ago
				},
				Watched:     map[string]bool{},
				Now:         testNow,
				Recency:     map[string]time.Time{"old1": testNow.Add(-2 * time.Hour), "new1": testNow.Add(-time.Minute), "mid1": testNow.Add(-time.Hour)},
				BuildBytes:  map[string]int64{"old1": 10, "new1": 10, "mid1": 10},
				PinCapBytes: 1000, // everything fits
			},
			wantPinned: []string{"new1", "mid1", "old1"},
			wantJobs:   []string{"new1", "mid1", "old1"},
		},
		{
			name: "stampless_serial_sorts_oldest_and_is_cap_cut_first",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("fresh1"), ep("fresh2")), // never watched: stampless
					serial(1, ep("watch1"), ep("watch2")), // stamped
				},
				Watched:     map[string]bool{},
				Now:         testNow,
				Recency:     map[string]time.Time{"watch1": testNow.Add(-time.Minute)},
				BuildBytes:  map[string]int64{"fresh1": 10, "watch1": 10},
				PinCapBytes: 10, // room for exactly the stamped serial
			},
			wantPinned: []string{"watch1"},
			wantJobs:   []string{"watch1"},
		},
		{
			name: "byte_overflow_ends_the_walk",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("big1"), ep("big2")),   // newest, 60 bytes
					serial(1, ep("over1"), ep("over2")), // 60 more: overflows the cap
					serial(1, ep("tiny1"), ep("tiny2")), // would fit alone — still unpinned
				},
				Watched:     map[string]bool{},
				Now:         testNow,
				Recency:     map[string]time.Time{"big1": testNow.Add(-time.Minute), "over1": testNow.Add(-2 * time.Hour), "tiny1": testNow.Add(-3 * time.Hour)},
				BuildBytes:  map[string]int64{"big1": 60, "over1": 60, "tiny1": 1},
				PinCapBytes: 100,
			},
			wantPinned: []string{"big1"},
			wantJobs:   []string{"big1"},
		},
		{
			name: "positions_that_exactly_fit_the_cap_stay_pinned",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("fit1"), ep("fit2")),   // 50 bytes
					serial(1, ep("over1"), ep("over2")), // 50+60 overflows
				},
				Watched:     map[string]bool{},
				Now:         testNow,
				Recency:     map[string]time.Time{"fit1": testNow.Add(-time.Minute), "over1": testNow.Add(-2 * time.Hour)},
				BuildBytes:  map[string]int64{"fit1": 50, "over1": 60},
				PinCapBytes: 50,
			},
			wantPinned: []string{"fit1"},
			wantJobs:   []string{"fit1"},
		},
		{
			name: "non_positive_cap_is_unbounded",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("a1"), ep("a2")),
					serial(1, ep("b1"), ep("b2")),
				},
				Watched:     map[string]bool{},
				Now:         testNow,
				BuildBytes:  map[string]int64{"a1": 1000, "b1": 1000},
				PinCapBytes: 0,
			},
			wantPinned: []string{"a1", "b1"},
			wantJobs:   []string{"a1", "b1"},
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			jobs, pinned, _ := Frontier(tc.in)
			if len(pinned) != len(tc.wantPinned) {
				t.Fatalf("Frontier() pinned = %v, want exactly %v", pinned, tc.wantPinned)
			}
			for _, id := range tc.wantPinned {
				if !pinned[id] {
					t.Fatalf("Frontier() pinned missing %q (got %v)", id, pinned)
				}
			}
			var bytes int64
			for id := range pinned {
				bytes += tc.in.BuildBytes[id]
			}
			if tc.in.PinCapBytes > 0 && bytes > tc.in.PinCapBytes {
				t.Fatalf("Frontier() pinned bytes = %d, over cap %d", bytes, tc.in.PinCapBytes)
			}
			ids := make([]string, len(jobs))
			for i, j := range jobs {
				ids[i] = j.ItemID
			}
			if len(ids) != len(tc.wantJobs) {
				t.Fatalf("Frontier() jobs = %v, want %v", ids, tc.wantJobs)
			}
			for i := range ids {
				if ids[i] != tc.wantJobs[i] {
					t.Fatalf("Frontier() jobs = %v, want %v (emission order)", ids, tc.wantJobs)
				}
			}
		})
	}
}

// TestFrontierDemote pins the demotion judgment (D2's policy half): every
// fully-watched serial's episode ids come back in input order (canonical
// order within a serial), a mixed serial is never demoted, and the gate
// holds — a streams-disabled serial's judgment is not this walk's. The
// executor is the shell's (task 1.2); this is data only.
func TestFrontierDemote(t *testing.T) {
	cases := []struct {
		name       string
		in         FrontierIn
		wantDemote []string // exact episode ids, in order
	}{
		{
			name: "fully_watched_serial_demoted_in_canonical_order",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("d1"), ep("d2"), ep("d3"))},
				Watched: map[string]bool{"d1": true, "d2": true, "d3": true},
				Now:     testNow,
			},
			wantDemote: []string{"d1", "d2", "d3"},
		},
		{
			name: "mixed_serial_never_demoted",
			in: FrontierIn{
				Serials: []Serial{serial(1, ep("m1"), ep("m2"), ep("m3"))},
				Watched: map[string]bool{"m2": true},
				Now:     testNow,
			},
			wantDemote: []string{},
		},
		{
			name: "fully_watched_serials_demote_in_input_order",
			in: FrontierIn{
				Serials: []Serial{
					serial(1, ep("a1"), ep("a2")),
					serial(1, ep("b1"), ep("b2")), // mixed: fronts b2 instead
					serial(1, ep("c1"), ep("c2")),
				},
				Watched: map[string]bool{"a1": true, "a2": true, "b1": true, "c1": true, "c2": true},
				Now:     testNow,
			},
			wantDemote: []string{"a1", "a2", "c1", "c2"},
		},
		{
			name: "streams_disabled_serial_is_not_demoted",
			in: FrontierIn{
				Serials: []Serial{{LibraryID: 2, StreamsEnabled: false, Episodes: []Episode{ep("x1"), ep("x2")}}},
				Watched: map[string]bool{"x1": true, "x2": true},
				Now:     testNow,
			},
			wantDemote: []string{},
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			_, _, demote := Frontier(tc.in)
			if demote == nil {
				t.Fatal("Frontier() demote = nil, want an empty non-nil slice")
			}
			if len(demote) != len(tc.wantDemote) {
				t.Fatalf("Frontier() demote = %v, want %v", demote, tc.wantDemote)
			}
			for i := range tc.wantDemote {
				if demote[i] != tc.wantDemote[i] {
					t.Fatalf("Frontier() demote = %v, want %v (input order)", demote, tc.wantDemote)
				}
			}
		})
	}
}
